<?php $this->load->view('admin/feeworkspace/_header'); ?>
<div class="fw-card"><div class="fw-card-head"><h3><i class="fa fa-search"></i> Enquiry</h3></div><div class="fw-card-body"><div class="fw-tabs" id="fw-enquiry-tabs"><?php if($can_payment_search){ ?><a href="#payment" data-tab="payment">Payment Receipt</a><?php } if($can_due_search){ ?><a href="#dues" data-tab="dues">Outstanding Fees</a><?php } if($can_reports){ ?><a href="#reports" data-tab="reports">Collection Summary</a><?php } if($can_reminders){ ?><a href="#reminders" data-tab="reminders">Reminders</a><?php } ?></div>
<?php if($can_payment_search){ ?><section class="fw-enquiry-pane" data-pane="payment"><form id="fw-payment-search"><div class="fw-toolbar" style="grid-template-columns:1fr auto"><div><label class="fw-label">Receipt ID</label><input class="form-control" id="fw-payment-id" placeholder="Example: 125/1" required></div><button class="fw-btn fw-btn-primary"><i class="fa fa-search"></i> Find Receipt</button></div></form><div id="fw-payment-result" class="fw-empty">Enter a receipt ID to view its details here.</div></section><?php } ?>
<?php if($can_due_search){ ?><section class="fw-enquiry-pane" data-pane="dues"><form id="fw-due-search"><div class="fw-toolbar"><div><label class="fw-label">Fee item</label><select class="form-control" id="fw-due-key" required><option value="">Select fee item</option><?php foreach($fee_types as $group){if(empty($group->feetypes))continue;foreach($group->feetypes as $f){?><option value="<?php echo (int)$group->id.'-'.(int)$f->id; ?>"><?php echo html_escape($group->group_name.' — '.$f->type); ?></option><?php }} ?></select></div><div><label class="fw-label">Class</label><select class="form-control fw-class" id="fw-due-class"><option value="">All classes</option><?php foreach($classlist as $c){?><option value="<?php echo (int)$c['id']; ?>"><?php echo html_escape($c['class']); ?></option><?php } ?></select></div><div><label class="fw-label">Section</label><select class="form-control" id="fw-due-section"><option value="">All sections</option></select></div><button class="fw-btn fw-btn-primary"><i class="fa fa-search"></i> Show Dues</button></div></form><div id="fw-due-result" class="fw-empty">Select a fee item to list outstanding students.</div></section><?php } ?>
<?php if($can_reports){ ?><section class="fw-enquiry-pane" data-pane="reports"><form id="fw-report-search"><div class="fw-toolbar" style="grid-template-columns:1fr 1fr auto"><div><label class="fw-label">From</label><input class="form-control" type="date" id="fw-report-start" value="<?php echo date('Y-m-01'); ?>" required></div><div><label class="fw-label">To</label><input class="form-control" type="date" id="fw-report-end" value="<?php echo date('Y-m-d'); ?>" required></div><button class="fw-btn fw-btn-primary"><i class="fa fa-bar-chart"></i> Build Summary</button></div></form><div id="fw-report-result" class="fw-empty">Choose a date range to build a live summary from the canonical fee ledger.</div></section><?php } ?>
<?php if($can_reminders){ ?><section class="fw-enquiry-pane" data-pane="reminders"><form id="fw-reminder-form"><div class="table-responsive"><table class="table fw-table"><thead><tr><th>Active</th><th>Reminder Type</th><th>Days</th></tr></thead><tbody><?php foreach($reminders as $r){ ?><tr><td><input type="checkbox" name="active[<?php echo (int)$r->id; ?>]" value="1" <?php echo $r->is_active?'checked':''; ?>><input type="hidden" name="ids[]" value="<?php echo (int)$r->id; ?>"></td><td><?php echo html_escape($this->lang->line($r->reminder_type)); ?></td><td><input class="form-control" style="max-width:130px" type="number" min="0" max="365" name="days[<?php echo (int)$r->id; ?>]" value="<?php echo (int)$r->day; ?>"></td></tr><?php } ?></tbody></table></div><?php if($this->rbac->hasPrivilege('fees_reminder','can_edit')){ ?><button class="fw-btn fw-btn-success" type="submit"><i class="fa fa-save"></i> Save Reminders</button><?php } ?><span id="fw-reminder-message" style="margin-left:10px"></span></form></section><?php } ?>
</div></div>
<script>(function($){
function esc(v){return $('<div>').text(v==null?'':v).html()}function busy(f,on,label){var b=f.find('[type=submit]');if(on){f.data('busy',1);b.prop('disabled',true).data('old',b.html()).html('<i class="fa fa-spinner fa-spin"></i> '+label)}else{f.data('busy',0);b.prop('disabled',false).html(b.data('old'))}}function table(rows,cols){if(!rows.length)return '<div class="fw-empty">No matching records found.</div>';var h='<div class="table-responsive"><table class="table table-hover fw-table"><thead><tr>';$.each(cols,function(_,c){h+='<th>'+esc(c[0])+'</th>'});h+='</tr></thead><tbody>';$.each(rows,function(_,r){h+='<tr>';$.each(cols,function(_,c){h+='<td'+(c[2]?' class="'+c[2]+'"':'')+'>'+esc(r[c[1]])+'</td>'});h+='</tr>'});return h+'</tbody></table></div>'}
var first=$('#fw-enquiry-tabs a:first').data('tab');function show(t){$('.fw-enquiry-pane').hide().filter('[data-pane="'+t+'"]').show();$('#fw-enquiry-tabs a').removeClass('active').filter('[data-tab="'+t+'"]').addClass('active')}$('#fw-enquiry-tabs a').on('click',function(e){e.preventDefault();show($(this).data('tab'))});show(first);
$('.fw-class').on('change',function(){var s=$('#fw-due-section').html('<option value="">All sections</option>');if(!this.value)return;$.getJSON('<?php echo site_url('sections/getByClass'); ?>',{class_id:this.value},function(a){$.each(a,function(_,x){s.append($('<option>').val(x.section_id||x.id).text(x.section))})})});
$('#fw-payment-search').on('submit',function(e){e.preventDefault();var f=$(this);busy(f,1,'Searching');$.post('<?php echo site_url('admin/feeworkspace/findPayment'); ?>',{payment_id:$('#fw-payment-id').val()},function(r){var p=r.payment;$('#fw-payment-result').html('<div class="row"><div class="col-sm-4"><h4>'+esc(p.student)+'</h4><p>'+esc(p.admission_no)+' · '+esc(p.class)+'</p></div><div class="col-sm-4"><strong>'+esc(p.fee)+'</strong><p>'+esc(p.date)+' · '+esc(p.mode)+'</p></div><div class="col-sm-4 text-right"><span class="fw-pill">Receipt '+esc(p.receipt)+'</span><h3>Rs. '+Number(p.amount).toFixed(2)+'</h3><small>Discount '+Number(p.discount).toFixed(2)+' · Fine '+Number(p.fine).toFixed(2)+'</small></div></div><div class="fw-actions"><a class="btn btn-success" href="<?php echo site_url('admin/feeworkspace/student'); ?>/'+p.student_session_id+'">Open Student Account</a><button type="button" class="btn btn-default" onclick="window.print()"><i class="fa fa-print"></i> Print</button></div>')},'json').fail(function(x){$('#fw-payment-result').html('<div class="alert alert-danger">'+esc(x.responseJSON?x.responseJSON.message:'Search failed.')+'</div>')}).always(function(){busy(f,0)})});
$('#fw-due-search').on('submit',function(e){e.preventDefault();var f=$(this);busy(f,1,'Loading');$.post('<?php echo site_url('admin/feeworkspace/findDueFees'); ?>',{fee_key:$('#fw-due-key').val(),class_id:$('#fw-due-class').val(),section_id:$('#fw-due-section').val()},function(r){$.each(r.rows,function(_,x){x.student=[x.firstname,x.middlename,x.lastname].filter(Boolean).join(' ');x.balance=Number(x.balance).toFixed(2);x.amount=Number(x.amount).toFixed(2);x.paid=Number(x.paid).toFixed(2)});$('#fw-due-result').html('<p><strong>'+r.count+' student(s) with outstanding balance</strong></p>'+table(r.rows,[['Admission','admission_no'],['Student','student'],['Class','class'],['Section','section'],['Due Date','due_date'],['Fee','amount','text-right'],['Paid','paid','text-right'],['Balance','balance','text-right']]))},'json').fail(function(x){$('#fw-due-result').html('<div class="alert alert-danger">'+esc(x.responseJSON?x.responseJSON.message:'Search failed.')+'</div>')}).always(function(){busy(f,0)})});
$('#fw-report-search').on('submit',function(e){e.preventDefault();var f=$(this);busy(f,1,'Building');$.post('<?php echo site_url('admin/feeworkspace/reportSummary'); ?>',{start_date:$('#fw-report-start').val(),end_date:$('#fw-report-end').val()},function(r){$.each(r.rows,function(_,x){x.amount=Number(x.amount).toFixed(2)});$('#fw-report-result').html('<div class="row"><div class="col-sm-4"><div class="small-box bg-green"><div class="inner"><h3>Rs. '+Number(r.totals.amount).toFixed(2)+'</h3><p>Collected ('+r.count+' receipts)</p></div></div></div><div class="col-sm-4"><div class="small-box bg-yellow"><div class="inner"><h3>Rs. '+Number(r.totals.discount).toFixed(2)+'</h3><p>Discount</p></div></div></div><div class="col-sm-4"><div class="small-box bg-aqua"><div class="inner"><h3>Rs. '+Number(r.totals.fine).toFixed(2)+'</h3><p>Fine</p></div></div></div></div>'+table(r.rows,[['Receipt','receipt'],['Date','date'],['Admission','admission_no'],['Student','student'],['Class','class'],['Fee','fee'],['Mode','mode'],['Amount','amount','text-right']]))},'json').fail(function(x){$('#fw-report-result').html('<div class="alert alert-danger">'+esc(x.responseJSON?x.responseJSON.message:'Report failed.')+'</div>')}).always(function(){busy(f,0)})});
$('#fw-reminder-form').on('submit',function(e){e.preventDefault();var f=$(this);busy(f,1,'Saving');$.post('<?php echo site_url('admin/feeworkspace/saveReminders'); ?>',f.serialize(),function(r){$('#fw-reminder-message').attr('class','text-success').text(r.message)},'json').fail(function(x){$('#fw-reminder-message').attr('class','text-danger').text(x.responseJSON?x.responseJSON.message:'Save failed.')}).always(function(){busy(f,0)})});
})(jQuery);</script>
